package main

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestAddNoasmBuildTags(t *testing.T) {
	t.Parallel()

	const input = `//go:build !noasm && amd64
// Code generated by GoAT. DO NOT EDIT.
// !noasm in an ordinary comment must not be changed.
`
	const want = `//go:build !noasm && !noasm_krypto && !noasm_krypto_lsh256 && amd64
// Code generated by GoAT. DO NOT EDIT.
// !noasm in an ordinary comment must not be changed.
`

	require.Equal(t, want, string(addNoasmBuildTags([]byte(input), "lsh256")))
}

func TestRewriteAssemblySymbols(t *testing.T) {
	const (
		input = `DATA s1<>+0x000(SB)/8, $0x0706050403020100
DATA s1<>+0x008(SB)/8, $0x0f0e0d0c0b0a0908
GLOBL s1<>(SB), 8, $16

DATA local<>+0x000(SB)/8, $0x0706050403020100
GLOBL local<>(SB), 8, $8

LEAQ s1<>(SB), R8
MOVD $KRK<>(SB), R12
MOVQ s1<>+8(SB), R13
`
		want = `DATA local<>+0x000(SB)/8, $0x0706050403020100
GLOBL local<>(SB), 8, $8

LEAQ ·s1(SB), R8
MOVD $·krk(SB), R12
MOVQ ·s1+8(SB), R13
`
	)
	t.Parallel()

	mappings, err := parseSymbolMappings([]string{"s1=s1", "KRK=krk"})
	require.NoError(t, err)
	got := rewriteAssemblySymbols(
		[]byte(input),
		mappings,
	)
	require.Equal(t, want, string(got), "unexpected rewrite")
	require.Equal(t, map[string]bool{"s1": true, "local": true, "KRK": true}, collectAssemblySymbols([]byte(input)))
}

func TestParseSymbolMappingsAcceptsCommaSeparatedValues(t *testing.T) {
	t.Parallel()

	got, err := parseSymbolMappings([]string{"s1=s1, KRK=krk", "x1=x1"})
	require.NoError(t, err)
	require.Equal(t, []symbolMapping{
		{from: "s1", to: "s1"},
		{from: "KRK", to: "krk"},
		{from: "x1", to: "x1"},
	}, got)
}

func TestParseSymbolMappingsRejectsInvalidMapping(t *testing.T) {
	t.Parallel()

	_, err := parseSymbolMappings([]string{"s1"})
	require.ErrorContains(t, err, "expected from=to")
}

func TestValidateSymbolTargets(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	require.NoError(t, os.WriteFile(filepath.Join(dir, "constants.go"), []byte("package target\nvar present int\nconst notAVariable = 1\n"), 0o644))
	require.NoError(t, validateSymbolTargets(dir, "target", map[string]bool{"present": true, "notAVariable": true}))

	err := validateSymbolTargets(dir, "target", map[string]bool{"missing": true})
	require.ErrorContains(t, err, "missing")
}

func TestValidateSymbolsUsedRejectsUnusedMappings(t *testing.T) {
	t.Parallel()

	err := validateSymbolsUsed([]symbolMapping{{from: "missing", to: "target"}}, map[string]bool{})
	require.ErrorContains(t, err, "missing")
}

func TestCollectAssemblySymbolsIgnoresComments(t *testing.T) {
	t.Parallel()

	got := collectAssemblySymbols([]byte("LEAQ used<>(SB), AX // ignored<>(SB)\nMOVQ $other<>(SB), BX\n"))
	require.Equal(t, map[string]bool{"used": true, "other": true}, got)
}

func TestFixBrokenRipLeaqInstructions(t *testing.T) {
	t.Parallel()

	const (
		input = `	LONG $0x000d8d48; WORD $0x0000; BYTE $0x00 // leaq	StepConstants+64(%rip), %rcx
	LONG $0x00058d4c; WORD $0x0000; BYTE $0x00 // leaq	BytePermInfo+16(%rip), %r8
	LEAQ ·step(SB), CX
`
		want = `	LEAQ StepConstants<>+64(SB), CX
	LEAQ BytePermInfo<>+16(SB), R8
	LEAQ ·step(SB), CX
`
	)

	got, err := fixBrokenRipLeaqInstructions([]byte(input))
	require.NoError(t, err)
	require.Equal(t, want, string(got))
}

func TestFixBrokenRipLeaqInstructionsRejectsUnknownRegister(t *testing.T) {
	t.Parallel()

	_, err := fixBrokenRipLeaqInstructions([]byte("\tLONG $0x000d8d48; WORD $0x0000; BYTE $0x00 // leaq\tStepConstants+64(%rip), %eax\n"))
	require.ErrorContains(t, err, "unrecognized register")
}

func TestRenamedAssemblySymbols(t *testing.T) {
	t.Parallel()

	got := renamedAssemblySymbols(
		map[string]bool{"original": true, "unchanged": true},
		[]symbolMapping{{from: "original", to: "replacement"}},
	)
	require.Equal(t, map[string]bool{"replacement": true, "unchanged": true}, got)
}
